func (p postgresQueries) TransitionSandbox(ctx context.Context, arg db.TransitionSandboxParams) (int64, error) {
	fromStates := arg.FromStates
	if fromStates == nil {
		fromStates = []string{}
	}
	states, err := json.Marshal(fromStates)
	if err != nil {
		return 0, err
	}
	return p.q.TransitionSandbox(ctx, postgres.TransitionSandboxParams{ToState: arg.ToState, Error: arg.Error, Now: arg.Now, AgentID: arg.AgentID, FromStates: states})
}

